def parse_demo_text(t):
    grids={}
    for pair,kind in re.findall(r'Demo pair (\d+) (input|output) \(30x24\):',t):
        start=t.index(f'Demo pair {pair} {kind} (30x24):')+len(f'Demo pair {pair} {kind} (30x24):')
        # exactly 30 following rows of integer tokens
        rows=[]
        for line in t[start:].strip().splitlines():
            vals=line.strip().split()
            if len(vals)==24 and all(v.isdigit() for v in vals):
                rows.append(list(map(int,vals)))
                if len(rows)==30: break
            elif rows: break
        grids[kind]=np.array(rows)
    return grids
