def canvases2(arr,bg):
    R,C=arr.shape; candidates=[]
    for r in range(R):
      if arr[r,0]!=bg and arr[r,-1]==arr[r,0] and np.all(arr[r,1:-1]==arr[r,1]):
        candidates.append((r,int(arr[r,0]),int(arr[r,1])))
    segs=[]
    for r,border,fill in candidates:
      if segs and r==segs[-1][1]+1 and border==segs[-1][2] and fill==segs[-1][3]:
        segs[-1]=(segs[-1][0],r,border,fill)
      else: segs.append((r,r,border,fill))
    return segs

def transfer2(arr):
    bg=int(np.bincount(arr.ravel()).argmax())
    out=arr.copy()
    cs=canvases2(arr,bg)
    firstpanel=min((x[0] for x in cs),default=arr.shape[0])
    out[:firstpanel,:]=bg
    comps=components(arr,bg,firstpanel)
    for color,cells in comps:
      targets=[x for x in cs if x[3]==color]
      if not targets:
        print('no target for',color)
        continue
      s,e,border,fill=targets[0]
      maxr=max(r for r,c in cells); dy=e-maxr
      for r,c in cells:
        if r+dy>=s: out[r+dy,c]=border
    return out

